// Rebuilds opening_signals from the detected_listings already in the database.
//
// monitor-run.ts writes a signal only when it INSERTS a listing, which is the
// right behaviour for a crawler - re-confirming a posting we already knew about
// is not news. It does mean the signals cannot be regenerated by re-running a
// sweep: the listings are already stored, so nothing is new and nothing fires.
//
// This walks what is stored and replays the same rule against it, so the
// signals table can be reconstructed without re-crawling every firm.
//
// The one real difference from a live crawl: `opensEnd` is set from the
// listing's first_detected_at rather than from now. That column records when
// this pipeline first saw the posting, which is exactly what "it had opened by
// then" means - and it is a more truthful answer than stamping everything with
// the time the backfill happened to run.
//
//   npx tsx --conditions=react-server scripts/backfill-opening-signals.ts
import { openScriptDb } from "./_db";
import * as schema from "../src/db/schema";
import { recordOpeningSignal } from "../src/lib/opening-signals";
import type { Classification } from "../src/lib/monitoring/classify";

async function main() {
  const { db, close: closeDb } = await openScriptDb();

  try {
    const sources = await db.select().from(schema.firmMonitoringSources);
    const listings = await db.select().from(schema.detectedListings);
    const firmOf = new Map(sources.map((s) => [s.id, s.firmId]));

    let written = 0;
    let skipped = 0;

    for (const l of listings) {
      const c = l.classification as Classification | null;
      if (!c?.relevant || !c.recruitingCycle) {
        skipped++;
        continue;
      }
      const firmId = firmOf.get(l.sourceId);
      if (!firmId) {
        skipped++;
        continue;
      }

      try {
        await recordOpeningSignal(
          {
            firmId,
            cycleYear: c.recruitingCycle,
            programCategory: c.sector,
            source: "seen_live",
            evidence: c.matchedEvidence.slice(0, 4).join(" | ") || l.title,
            sourceUrl: l.listingUrl,
            // "It had opened by the time we first saw it" - never a start date,
            // which finding a live posting cannot tell us.
            opensEnd: l.firstDetectedAt,
            // The stated closing date, now that detected_listings keeps one.
            // Without it a rebuilt signal cannot land in "Open now", which is
            // exactly what happened the first time this script ran.
            closesStart: l.deadlineAt,
            closesEnd: l.deadlineAt,
            observedAt: l.firstDetectedAt,
          },
          db,
        );
        written++;
      } catch {
        // recordOpeningSignal dedupes per (firm, cycle, category, source), so
        // most listings collapse into one row. A failure on one listing should
        // not abandon the rest.
        skipped++;
      }
    }

    const rows = await db.select().from(schema.openingSignals);
    console.log(`processed ${listings.length} listings: ${written} recorded, ${skipped} skipped`);
    console.log(`opening_signals now holds ${rows.length} rows`);
  } finally {
    await closeDb();
  }
}

main();
